-- Local demo data for docker compose. Generated from the prototype's sample menu; safe to re-run (it does nothing once an outlet exists).
-- Staff sign in locally as Bearer dev-<user_id> (backend profile "local").
do $$
declare v_org uuid; v_out uuid; v_owner uuid; i int;
begin
  if exists (select 1 from pos.outlets) then return; end if;
  select id into v_owner from pos.staff_members where outlet_id = v_out and role = 'owner';
  for i in 1..12 loop insert into pos.dining_tables(outlet_id, label, seats) values (v_out, 'T' || i, 4); end loop;

end $$;
